1	package components
2	
3	import (
4		"strings"
5		"testing"
6		"time"
7	
8		"github.com/anthnel/devdesk/internal/jobs"
9		"github.com/anthnel/devdesk/internal/ui/indicator"
10	)
11	
12	func TestRunIndicator(t *testing.T) {
13		want := map[jobs.RunState]indicator.State{
14			jobs.RunQueued:    indicator.Queued,
15			jobs.RunRunning:   indicator.Running,
16			jobs.RunDone:      indicator.Done,
17			jobs.RunFailed:    indicator.Failed,
18			jobs.RunCancelled: indicator.Cancelled,
19		}
20		seen := map[indicator.State]bool{}
21		for rs, st := range want {
22			got := RunIndicator(rs)
23			if got != st {
24				t.Errorf("RunIndicator(%q) = %v, want %v", rs, got, st)
25			}
26			if got == indicator.Idle || seen[got] {
27				t.Errorf("RunIndicator(%q) = %v: Idle or not distinct", rs, got)
28			}
29			seen[got] = true
30		}
31	}
32	
33	func TestItemIndicator(t *testing.T) {
34		want := map[jobs.ItemState]indicator.State{
35			jobs.ItemQueued:  indicator.Queued,
36			jobs.ItemRunning: indicator.Running,
37			jobs.ItemDone:    indicator.Done,
38			jobs.ItemSkipped: indicator.Skipped,
39			jobs.ItemFailed:  indicator.Failed,
40		}
41		seen := map[indicator.State]bool{}
42		for is, st := range want {
43			got := ItemIndicator(is)
44			if got != st {
45				t.Errorf("ItemIndicator(%q) = %v, want %v", is, got, st)
46			}
47			if got == indicator.Idle || seen[got] {
48				t.Errorf("ItemIndicator(%q) = %v: Idle or not distinct", is, got)
49			}
50			seen[got] = true
51		}
52	}
53	
54	// jobRun builds a run of kind on label with one item per state given.
55	func jobRun(kind jobs.Kind, label string, states ...jobs.ItemState) jobs.Run {
56		targets := make([]string, len(states))
57		for i := range states {
58			targets[i] = label + "/t" + string(rune('a'+i))
59		}
60		r := jobs.NewRun(kind, "", rowCtx, label, targets...)
61		for i, s := range states {
62			r.Items[i].State = s
63		}
64		return r
65	}
66	
67	func withFailure(r jobs.Run, idx int, detail string) jobs.Run {
68		r.Items[idx].State = jobs.ItemFailed
69		r.Items[idx].Detail = detail
70		return r
71	}
72	
73	func TestDescribeRun(t *testing.T) {
74		isolateRowHome(t)
75		const app = "/home/u/w/app"
76		now := time.Now()
77	
78		done2 := jobRun(jobs.KindScan, app, jobs.ItemDone)
79		done2.EndedAt = now.Add(-2 * time.Minute)
80		doneNow := jobRun(jobs.KindScan, app, jobs.ItemDone)
81		doneNow.EndedAt = now.Add(-10 * time.Second)
82		doneZero := jobRun(jobs.KindScan, app, jobs.ItemDone)
83		failOne := withFailure(jobRun(jobs.KindScan, app, jobs.ItemDone, jobs.ItemDone), 1, "scan failed: db")
84		failMany := withFailure(withFailure(jobRun(jobs.KindScan, app, jobs.ItemDone, jobs.ItemDone, jobs.ItemDone), 0, "a"), 1, "b")
85		failNoDetail := withFailure(jobRun(jobs.KindScan, app, jobs.ItemDone), 0, "")
86		bidi := withFailure(jobRun(jobs.KindScan, app, jobs.ItemDone), 0, "line1\nline2‮ x")
87	
88		// A cancelled run can only be reached through the registry.
89		reg := jobs.New()
90		id := reg.Start(jobs.NewRun(jobs.KindScan, "", rowCtx, app, app+"/ta"))
91		if !reg.Cancel(id) {
92			t.Fatal("Cancel refused")
93		}
94		snap := reg.Snapshot()
95		if len(snap) != 1 || snap[0].State() != jobs.RunCancelled {
96			t.Fatalf("fixture is not a cancelled run: %+v", snap)
97		}
98	
99		tests := []struct {
100			name  string
101			run   jobs.Run
102			state indicator.State
103			want  string
104		}{
105			{"running", jobRun(jobs.KindScan, app, jobs.ItemRunning, jobs.ItemQueued), indicator.Running, "● Scanning ~/w/app"},
106			{"queued", jobRun(jobs.KindScan, app, jobs.ItemQueued), indicator.Queued, "◴ Queued: scan ~/w/app"},
107			{"done 2 min ago", done2, indicator.Done, "◉ Scan of ~/w/app finished 2 min ago"},
108			{"done under a minute", doneNow, indicator.Done, "◉ Scan of ~/w/app finished now"},
109			{"done without end time", doneZero, indicator.Done, "◉ Scan of ~/w/app finished"},
110			{"cancelled", snap[0], indicator.Cancelled, "⊘ Scan of ~/w/app was cancelled"},
111			{"failed, one cause", failOne, indicator.Failed, "⊗ ~/w/app: last scan failed — db"},
112			{"failed, several", failMany, indicator.Failed, "⊗ ~/w/app: last scan failed — 2 of 3 targets failed"},
113			{"failed, no detail", failNoDetail, indicator.Failed, "⊗ ~/w/app: last scan failed"},
114			{"failed, multi-line bidi", bidi, indicator.Failed, "⊗ ~/w/app: last scan failed — line1 line2 x"},
115			{"pull capitalized", func() jobs.Run {
116				r := jobRun(jobs.KindPull, "img", jobs.ItemDone)
117				r.EndedAt = now.Add(-2 * time.Minute)
118				return r
119			}(), indicator.Done, "◉ Pull of img finished 2 min ago"},
120		}
121		for _, tt := range tests {
122			t.Run(tt.name, func(t *testing.T) {
123				got := DescribeRun(tt.run)
124				if got.State != tt.state {
125					t.Errorf("State = %v, want %v", got.State, tt.state)
126				}
127				if got.State != RunIndicator(tt.run.State()) {
128					t.Errorf("State %v disagrees with RunIndicator(%v)", got.State, tt.run.State())
129				}
130				if s := got.Detail.String(); s != tt.want {
131					t.Errorf("Detail = %q, want %q", s, tt.want)
132				}
133				if g := indicator.Glyph(tt.state, true); !strings.HasPrefix(got.Detail.String(), g) {
134					t.Errorf("Detail does not start with glyph %q", g)
135				}
136			})
137		}
138	}
