162			it    jobs.Item
163			state indicator.State
164			want  string
165		}{
166			{"running", jobs.KindScan, item(jobs.ItemRunning, ""), indicator.Running, "● Scanning ~/w/a"},
167			{"queued", jobs.KindScan, item(jobs.ItemQueued, ""), indicator.Queued, "◴ Queued: scan ~/w/a"},
168			{"done", jobs.KindScan, item(jobs.ItemDone, ""), indicator.Done, "◉ Scan of ~/w/a finished"},
169			{"skipped with detail", jobs.KindSync, item(jobs.ItemSkipped, "already there"), indicator.Skipped, "⊖ Sync of ~/w/a skipped — already there"},
170			{"skipped without detail", jobs.KindSync, item(jobs.ItemSkipped, ""), indicator.Skipped, "⊖ Sync of ~/w/a skipped"},
171			{"failed", jobs.KindScan, item(jobs.ItemFailed, "scan failed: db"), indicator.Failed, "⊗ ~/w/a: last scan failed — db"},
172			{"failed multi-line", jobs.KindScan, item(jobs.ItemFailed, "x\ny‮"), indicator.Failed, "⊗ ~/w/a: last scan failed — x y"},
173			{"display name", jobs.KindPull, jobs.Item{Target: "reg/x:1", Display: "x:1", State: jobs.ItemDone}, indicator.Done, "◉ Pull of x:1 finished"},
174		}
175		for _, tt := range tests {
176			t.Run(tt.name, func(t *testing.T) {
177				got := DescribeItem(tt.kind, tt.it)
178				if got.State != tt.state || got.State != ItemIndicator(tt.it.State) {
