				Title: "Note", Sizing: SizingContent, MinWidth: 8,
				Cell:   func(r row) string { return "" },
				Search: func(r row) string { return "" },
			},
			{
				Title: "Plain", Sizing: SizingFixed, MinWidth: 4,
				Cell: func(r row) string { return "" },
			},
		},
