	m := New(shapeConfig())
	first := m.Shapes()
	if len(first) == 0 {
		t.Fatal("Shapes() is empty")
	}
	first[0].Title = "mutated"
	if got := m.Shapes()[0].Title; got != "" {
		t.Fatalf("mutating the result changed the table: title %q", got)
	}
}

